smart.css:
.smc-root{line-height:1.6;color:var(--smc-text)}.smc-root h2{font-family:var(--smc-font-heading);font-size:1.25rem;margin:1.6rem 0 .8rem;padding-left:.6rem;border-left:4px solid var(--smc-accent)}.smc-root p{margin:0 0 .7rem}.smc-intro{display:flex;gap:1rem;align-items:center}.smc-intro img{width:40%;height:auto;border-radius:var(--smc-radius);border:1px solid var(--smc-border)}.smc-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem;margin-top:1rem}.smc-stats div{background:var(--smc-surface);border-radius:var(--smc-radius);padding:.8rem .4rem;text-align:center}.smc-stats b{display:block;color:var(--smc-primary);font-size:1.2rem}.smc-stats span{color:var(--smc-muted);font-size:.85rem}.smc-list{list-style:none}.smc-list li{padding:.5rem .8rem;margin-bottom:.4rem;background:var(--smc-surface);border-radius:var(--smc-radius);border-left:3px solid var(--smc-primary)}.smc-table{width:100%;border-collapse:collapse}.smc-table th,.smc-table td{text-align:left;padding:.55rem .7rem;border-bottom:1px solid var(--smc-border);vertical-align:top}.smc-table th{width:40%;background:var(--smc-surface);font-weight:600}.smc-cap{color:var(--smc-muted);font-size:.9rem}@container smc (max-width:520px){.smc-intro{flex-direction:column}.smc-intro img{width:100%}.smc-stats b{font-size:1rem}}

.smc-links{list-style:none}.smc-links li{margin-bottom:.4rem}.smc-links a{display:block;padding:.6rem .8rem;background:var(--smc-surface);border-radius:var(--smc-radius);border-left:3px solid var(--smc-accent);color:var(--smc-primary);font-weight:600;text-decoration:none}.smc-links a:hover{text-decoration:underline}

.smc-root p a{color:var(--smc-primary);font-weight:600;text-decoration:underline}

